-- DEPORTE · Fase 1 · migración para guardar entrenamientos de forma atómica
-- Revisa y ejecuta en Supabase SQL Editor. Incluye una transacción implícita por sentencia RPC.

begin;

alter table public.entrenamientos
  add column if not exists motivo_incompleto text;

-- Las consultas confirmaron que ambos IDs ya son GENERATED BY DEFAULT AS IDENTITY.
-- No modificamos su generación ni sus secuencias.

-- Permite el nuevo estado sin perder los estados admitidos previamente.
alter table public.entrenamientos
  drop constraint if exists entrenamientos_estado_valido;
alter table public.entrenamientos
  add constraint entrenamientos_estado_valido
  check (estado = any (array['en_curso'::text, 'completado'::text, 'cancelado'::text, 'incompleto'::text]));

-- Refuerza la coherencia del motivo: obligatorio para incompletos y nulo para completados.
-- El estado cancelado conserva el comportamiento previo.
alter table public.entrenamientos
  drop constraint if exists entrenamientos_motivo_incompleto_valido;
alter table public.entrenamientos
  add constraint entrenamientos_motivo_incompleto_valido
  check (
    (estado = 'incompleto' and motivo_incompleto is not null and motivo_incompleto = any (array[
      'falta_tiempo'::text, 'fatiga'::text, 'molestias'::text,
      'dificultad'::text, 'interrupcion'::text, 'otro'::text
    ]))
    or (estado = 'completado' and motivo_incompleto is null)
    or (estado in ('en_curso', 'cancelado') and (motivo_incompleto is null or motivo_incompleto = any (array[
      'falta_tiempo'::text, 'fatiga'::text, 'molestias'::text,
      'dificultad'::text, 'interrupcion'::text, 'otro'::text
    ])))
  );

create or replace function public.guardar_entrenamiento(p_entrenamiento jsonb)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_entrenamiento_id bigint;
  v_estado text;
  v_motivo text;
  v_nombre text;
  v_fecha_inicio timestamptz;
  v_fecha_fin timestamptz;
  v_series jsonb;
  v_item jsonb;
  v_ejercicio_id bigint;
  v_numero_serie integer;
  v_repeticiones integer;
  v_duracion integer;
  v_peso numeric;
  v_completada boolean;
begin
  if v_user_id is null then
    raise exception 'Debes iniciar sesión para guardar un entrenamiento.' using errcode='42501';
  end if;
  if jsonb_typeof(p_entrenamiento) <> 'object' then
    raise exception 'Datos de entrenamiento no válidos.' using errcode='22023';
  end if;

  v_estado := p_entrenamiento->>'estado';
  v_motivo := nullif(p_entrenamiento->>'motivo_incompleto','');
  v_nombre := nullif(trim(p_entrenamiento->>'nombre'),'');
  v_fecha_inicio := coalesce(nullif(p_entrenamiento->>'fecha_inicio','')::timestamptz, now());
  v_fecha_fin := coalesce(nullif(p_entrenamiento->>'fecha_fin','')::timestamptz, now());
  v_series := p_entrenamiento->'series';

  if v_estado is null or v_estado not in ('completado','incompleto') then
    raise exception 'Estado de entrenamiento no válido.' using errcode='22023';
  end if;
  if v_nombre is null then
    raise exception 'El entrenamiento necesita un nombre.' using errcode='22023';
  end if;
  if v_estado='incompleto' and (v_motivo is null or v_motivo not in ('falta_tiempo','fatiga','molestias','dificultad','interrupcion','otro')) then
    raise exception 'Selecciona un motivo válido para la sesión incompleta.' using errcode='22023';
  end if;
  if v_estado='completado' then v_motivo := null; end if;
  if v_series is null
     or jsonb_typeof(v_series) <> 'array'
     or jsonb_array_length(v_series) = 0 then
    raise exception 'El entrenamiento debe incluir al menos una serie.' using errcode='22023';
  end if;

  insert into public.entrenamientos(user_id, nombre, estado, motivo_incompleto, fecha_inicio, fecha_fin)
  values (v_user_id, v_nombre, v_estado, v_motivo, v_fecha_inicio, v_fecha_fin)
  returning id into v_entrenamiento_id;

  for v_item in select value from jsonb_array_elements(v_series)
  loop
    if jsonb_typeof(v_item) <> 'object'
       or nullif(v_item->>'ejercicio_id','') is null
       or nullif(v_item->>'numero_serie','') is null then
      raise exception 'Cada serie debe incluir ejercicio y número de serie.' using errcode='22023';
    end if;

    v_ejercicio_id := (v_item->>'ejercicio_id')::bigint;
    v_numero_serie := (v_item->>'numero_serie')::integer;
    v_repeticiones := nullif(v_item->>'repeticiones','')::integer;
    v_duracion := nullif(v_item->>'duracion_segundos','')::integer;
    v_peso := nullif(v_item->>'peso_kg','')::numeric;
    v_completada := coalesce((v_item->>'completada')::boolean,false);

    if v_numero_serie is null or v_numero_serie < 1 then
      raise exception 'Número de serie no válido.' using errcode='22023';
    end if;
    if (v_repeticiones is null) = (v_duracion is null) then
      raise exception 'Cada serie debe indicar repeticiones o duración, pero no ambas.' using errcode='22023';
    end if;
    if (v_repeticiones is not null and (v_repeticiones < 1 or v_repeticiones > 50))
       or (v_duracion is not null and (v_duracion < 1 or v_duracion > 300)) then
      raise exception 'Las repeticiones deben estar entre 1 y 50, o la duración entre 1 y 300 segundos.' using errcode='22023';
    end if;
    if v_peso is not null and v_peso < 0 then
      raise exception 'El peso no puede ser negativo.' using errcode='22023';
    end if;

    insert into public.entrenamiento_series(
      entrenamiento_id, ejercicio_id, numero_serie, repeticiones,
      duracion_segundos, peso_kg, completada
    ) values (
      v_entrenamiento_id, v_ejercicio_id, v_numero_serie, v_repeticiones,
      v_duracion, v_peso, v_completada
    );
  end loop;

  return jsonb_build_object('id',v_entrenamiento_id,'estado',v_estado,'motivo_incompleto',v_motivo);
end;
$$;

revoke all on function public.guardar_entrenamiento(jsonb) from public, anon;
grant execute on function public.guardar_entrenamiento(jsonb) to authenticated;

commit;
